                "Lê JSON diretamente do corpo. Processa pelo ID da cobrança e evento. Responde 200 sem corpo inclusive para payload vazio, inválido ou erro interno; 200 não confirma alteração no banco. Nesta versão a rota é pública e não declara verificação de assinatura/token de webhook.",
                new ResponseDocumentation(200, "Operação concluída.")),
        };
}

internal sealed record OperationDocumentation(string Summary, string Description, params ResponseDocumentation[] Responses);
internal sealed record ResponseDocumentation(int Status, string Description, Type? BodyType = null, string? ExampleJson = null);
